import assert from'node:assert/strict';import fs from'node:fs';import crypto from'node:crypto';import{render,sample}from'./clock-v15.mjs';import{render as old,overlapCases}from'../v14/clock-v14.mjs';
const norm=s=>s.replace(/v6-\d+/g,'ID');let count=0;for(let end=1;end<=12;end++)for(const c of overlapCases)for(const growth of[0,50,100]){const state={...sample,...c.state,end,firstGrowth:growth,secondGrowth:100-growth};for(const v of['A','B','C','D'])assert.equal(norm(render(state,{variant:v})),norm(old(state,{variant:v==='D'?'C':v})));count++;}
const s=fs.readFileSync(new URL('stand-A.svg',import.meta.url),'utf8'),b=Buffer.from(s.match(/data:image\/jpeg;base64,([^"]+)/)[1],'base64'),d=fs.readFileSync(new URL('evidence/D-full.jpg',import.meta.url));assert.deepEqual(b,d);const m=JSON.parse(fs.readFileSync(new URL('evidence/stand-integrity.json',import.meta.url)));assert.equal(crypto.createHash('sha256').update(b).digest('hex'),m.sha256);assert.equal(m.frontImageHeight,m.frontImageWidth);assert.ok(s.includes('width="24" height="240" transform="rotate(12 430 190)"'));assert.ok(!s.includes('v13/evidence'));
console.log({cases:count,variants:4,frontBytesIdentical:true,uniformScale:true,ringFixed:false});
